import vine from '@vinejs/vine'
import type Tag from '#models/tag'

/**
 * Generated by `node ace make:admin-resource Tag --policy`: create and
 * update validators for Tag, derived from its database columns.
 *
 * A starting point: edit it freely; Azu never regenerates it.
 */
export const createTagValidator = vine.create({
  name: vine.string().trim().maxLength(60),
  slug: vine.string().trim().maxLength(80).unique({ table: 'tags', column: 'slug' }),
  productIds: vine.array(vine.number().exists({ table: 'products', column: 'id' })).optional(),
})

/**
 * Azu passes `{ record }` as metadata: the tag being edited, so its
 * own values don't count as taken.
 */
export const updateTagValidator = vine.withMetaData<{ record: Tag }>().create({
  name: vine.string().trim().maxLength(60),
  slug: vine
    .string()
    .trim()
    .maxLength(80)
    .unique({
      table: 'tags',
      column: 'slug',
      filter: (query, _value, field) => {
        query.whereNot('id', field.meta.record.id)
      },
    }),
  productIds: vine.array(vine.number().exists({ table: 'products', column: 'id' })).optional(),
})
